adcs_vec3_t delta;
double delta_norm;
adcs_vec3_t unit_delta;
adcs_vec3_t scaled;
adcs_status_t status;

if ((previous == NULL) || (target == NULL) || (next == NULL) || (limited == NULL)) {
    return ADCS_E_NULL;
}

if ((!adcs_is_finite_vec3(previous)) || (!adcs_is_finite_vec3(target)) ||
    (!isfinite(max_delta_nm)) || (max_delta_nm < 0.0)) {
    *next = (adcs_vec3_t){0, 0, 0};
    *limited = 0;
    return ADCS_E_RANGE;
}

delta = adcs_vec3_sub(target, previous);
delta_norm = adcs_vec3_norm(&delta);

if (delta_norm <= max_delta_nm) {
    *next = *target;
    *limited = 0;
    return ADCS_OK;
}

status = adcs_vec3_normalize(&delta, ADCS_EPS_NORM, &unit_delta);
if (status != ADCS_OK) {
    *next = (adcs_vec3_t){0, 0, 0};
    *limited = 0;
    return ADCS_E_RANGE;
}

scaled = adcs_vec3_scale(&unit_delta, max_delta_nm);
*next = adcs_vec3_add(previous, &scaled);
*limited = 1;
return ADCS_OK;

